-- ProTik draft schema. NOT a Flyway migration: real migrations are created
-- per ticket (CONTRIBUTING.md section 4). This file is the reviewed design
-- baseline, validated by tests.sql against PostgreSQL 17. See ADR 0005.
--
-- Conventions
--   * One PostgreSQL schema per module; NO foreign keys across schemas.
--   * Primary keys are UUIDs generated by the application (UUIDv7).
--   * Evolving value sets are lookup tables; state machines use CHECK.
--   * timestamptz everywhere, UTC.
-- Requires PostgreSQL 15+ (UNIQUE NULLS NOT DISTINCT).

CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE SCHEMA identity;
CREATE SCHEMA video;
CREATE SCHEMA feed;
CREATE SCHEMA social;
CREATE SCHEMA engagement;
CREATE SCHEMA moderation;
CREATE SCHEMA shared;

-- unaccent() is only STABLE, so it cannot be used in generated columns or
-- index expressions. This wrapper is the standard workaround; it is safe
-- as long as the unaccent dictionary is never changed after data exists.
CREATE FUNCTION shared.immutable_unaccent(text) RETURNS text
  LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
  AS $$ SELECT public.unaccent('public.unaccent'::regdictionary, $1) $$;

-- ====================================================================
-- shared: job queue (ADR 0003) and idempotency keys
-- ====================================================================
CREATE TABLE shared.jobs (
  id               uuid PRIMARY KEY,
  type             text        NOT NULL,
  payload          jsonb       NOT NULL DEFAULT '{}',
  status           text        NOT NULL DEFAULT 'QUEUED'
                     CHECK (status IN ('QUEUED','RUNNING','DONE','DEAD')),
  attempts         int         NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  max_attempts     int         NOT NULL DEFAULT 5 CHECK (max_attempts > 0),
  run_at           timestamptz NOT NULL DEFAULT now(),
  lease_expires_at timestamptz,
  last_error       text,
  created_at       timestamptz NOT NULL DEFAULT now(),
  CHECK ((status = 'RUNNING') = (lease_expires_at IS NOT NULL))
);
-- Serves claiming: SELECT ... WHERE status='QUEUED' AND run_at<=now()
--   ORDER BY run_at FOR UPDATE SKIP LOCKED
CREATE INDEX jobs_claim_idx ON shared.jobs (run_at) WHERE status = 'QUEUED';
-- Serves lease recovery: re-queue RUNNING jobs whose lease expired
CREATE INDEX jobs_lease_idx ON shared.jobs (lease_expires_at) WHERE status = 'RUNNING';

CREATE TABLE shared.idempotency_keys (
  user_id         uuid        NOT NULL,
  key             text        NOT NULL CHECK (length(key) BETWEEN 1 AND 255),
  endpoint        text        NOT NULL,
  request_hash    bytea       NOT NULL,   -- same key + different hash is rejected
  response_status int,                    -- NULL while the first request is in flight
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  expires_at      timestamptz NOT NULL,
  PRIMARY KEY (user_id, key)
);
-- Serves the periodic cleanup of expired keys
CREATE INDEX idempotency_expiry_idx ON shared.idempotency_keys (expires_at);

-- ====================================================================
-- identity
-- ====================================================================
CREATE TABLE identity.accounts (
  id         uuid PRIMARY KEY,
  username   citext      NOT NULL UNIQUE CHECK (username ~ '^[a-z0-9_.]{3,30}$'),
  status     text        NOT NULL DEFAULT 'ACTIVE'
               CHECK (status IN ('ACTIVE','SUSPENDED','DELETION_PENDING')),
  created_at timestamptz NOT NULL DEFAULT now()
);

-- A user may have several login identifiers (many Nigerian users sign in
-- with a phone number). Kept apart from the account: 3NF.
CREATE TABLE identity.login_identifiers (
  id          uuid PRIMARY KEY,
  account_id  uuid        NOT NULL REFERENCES identity.accounts(id) ON DELETE CASCADE,
  kind        text        NOT NULL CHECK (kind IN ('EMAIL','PHONE')),
  value       citext      NOT NULL,
  verified_at timestamptz,
  UNIQUE (kind, value)
);
-- FK index: cascade delete and "identifiers of an account"
CREATE INDEX login_identifiers_account_idx ON identity.login_identifiers (account_id);

CREATE TABLE identity.password_credentials (
  account_id    uuid PRIMARY KEY REFERENCES identity.accounts(id) ON DELETE CASCADE,
  password_hash text        NOT NULL,   -- Argon2/bcrypt output only
  updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE identity.profiles (
  account_id         uuid PRIMARY KEY REFERENCES identity.accounts(id) ON DELETE CASCADE,
  display_name       text NOT NULL DEFAULT '' CHECK (length(display_name) <= 50),
  bio                text NOT NULL DEFAULT '' CHECK (length(bio) <= 300),
  avatar_key         text,
  preferred_language text
);

CREATE TABLE identity.session_families (
  id             uuid PRIMARY KEY,
  account_id     uuid        NOT NULL REFERENCES identity.accounts(id) ON DELETE CASCADE,
  created_at     timestamptz NOT NULL DEFAULT now(),
  revoked_at     timestamptz,
  revoked_reason text CHECK (revoked_reason IN ('LOGOUT','TOKEN_REUSE','ADMIN','ACCOUNT_DELETION')),
  CHECK ((revoked_at IS NULL) = (revoked_reason IS NULL))
);
-- Serves "log out everywhere" and revoke-on-deletion
CREATE INDEX session_families_account_idx ON identity.session_families (account_id);

CREATE TABLE identity.refresh_tokens (
  id         uuid PRIMARY KEY,
  family_id  uuid        NOT NULL REFERENCES identity.session_families(id) ON DELETE CASCADE,
  token_hash bytea       NOT NULL UNIQUE,   -- hash only; the token itself is never stored
  issued_at  timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  rotated_at timestamptz,                   -- set when exchanged; presenting it again = reuse
  CHECK (expires_at > issued_at)
);
-- FK index: revoke every token in a family
CREATE INDEX refresh_tokens_family_idx ON identity.refresh_tokens (family_id);

-- Account deletion across modules without cross-schema FKs (ADR 0005 #5)
CREATE TABLE identity.deletion_requests (
  id           uuid PRIMARY KEY,
  account_id   uuid        NOT NULL UNIQUE,   -- no FK: the account row is purged last
  requested_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz
);
CREATE TABLE identity.deletion_acks (
  request_id uuid        NOT NULL REFERENCES identity.deletion_requests(id) ON DELETE CASCADE,
  module     text        NOT NULL
               CHECK (module IN ('video','feed','social','engagement','moderation')),
  acked_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (request_id, module)
);

-- ====================================================================
-- video
-- ====================================================================
CREATE TABLE video.languages (
  code          text PRIMARY KEY,            -- BCP 47 / ISO: yo, ig, ha, pcm, en
  name          text    NOT NULL,
  asr_supported boolean NOT NULL DEFAULT false
);

CREATE TABLE video.renditions (
  code             text PRIMARY KEY,         -- '144p','240p','480p','720p','audio'
  height_px        int,                      -- NULL for audio-only
  max_bitrate_kbps int NOT NULL CHECK (max_bitrate_kbps > 0),
  CHECK (height_px IS NULL OR height_px > 0)
);

CREATE TABLE video.videos (
  id              uuid PRIMARY KEY,
  creator_id      uuid        NOT NULL,      -- identity.accounts; no FK (ADR 0005)
  description     text        NOT NULL DEFAULT '' CHECK (length(description) <= 2200),
  spoken_language text REFERENCES video.languages(code),
  duration_ms     int         CHECK (duration_ms > 0),
  status          text        NOT NULL
                    CHECK (status IN ('UPLOADING','PROCESSING','PUBLISHED','FAILED','TAKEN_DOWN')),
  created_at      timestamptz NOT NULL DEFAULT now(),
  published_at    timestamptz,
  -- No DELETED status: deletion really deletes the row (NDPA, VISION.md).
  CHECK (status <> 'PUBLISHED' OR (published_at IS NOT NULL AND duration_ms IS NOT NULL))
);
-- Serves a creator's profile page, cursor-paginated by (published_at, id)
CREATE INDEX videos_creator_pub_idx
  ON video.videos (creator_id, published_at DESC, id DESC) WHERE status = 'PUBLISHED';
-- FK index for spoken_language
CREATE INDEX videos_language_idx ON video.videos (spoken_language);

CREATE TABLE video.upload_sessions (
  id                  uuid PRIMARY KEY,
  creator_id          uuid        NOT NULL,
  video_id            uuid        NOT NULL UNIQUE REFERENCES video.videos(id) ON DELETE CASCADE,
  storage_key         text        NOT NULL UNIQUE,
  multipart_upload_id text        NOT NULL,
  content_type        text        NOT NULL,
  total_bytes         bigint      NOT NULL CHECK (total_bytes > 0),
  status              text        NOT NULL CHECK (status IN ('OPEN','COMPLETED','ABORTED','EXPIRED')),
  created_at          timestamptz NOT NULL DEFAULT now(),
  expires_at          timestamptz NOT NULL,
  CHECK (expires_at > created_at)
);
-- Serves the sweeper that aborts expired multipart uploads (frees storage)
CREATE INDEX upload_sessions_expiry_idx ON video.upload_sessions (expires_at) WHERE status = 'OPEN';

CREATE TABLE video.video_assets (
  id              uuid PRIMARY KEY,
  video_id        uuid        NOT NULL REFERENCES video.videos(id) ON DELETE CASCADE,
  kind            text        NOT NULL
                    CHECK (kind IN ('ORIGINAL','HLS_MASTER','HLS_VARIANT','THUMBNAIL')),
  rendition_code  text        REFERENCES video.renditions(code),
  storage_key     text        NOT NULL UNIQUE,   -- object key or key prefix for HLS variants
  size_bytes      bigint      NOT NULL CHECK (size_bytes >= 0),  -- total across objects
  object_count    int         NOT NULL DEFAULT 1 CHECK (object_count > 0),
  avg_bitrate_kbps int        CHECK (avg_bitrate_kbps > 0),      -- measured, not the ladder maximum
  created_at      timestamptz NOT NULL DEFAULT now(),
  -- Only variants carry a rendition; makes "audio-only" a real, queryable variant.
  CHECK ((kind = 'HLS_VARIANT') = (rendition_code IS NOT NULL)),
  -- A re-run of the transcode job cannot create duplicate assets (idempotent).
  UNIQUE NULLS NOT DISTINCT (video_id, kind, rendition_code)
);
-- FK index for rendition_code; also serves "storage cost per rendition" reports
CREATE INDEX video_assets_rendition_idx ON video.video_assets (rendition_code);

-- Deleting rows must never orphan objects in MinIO/S3. A trigger records every
-- deleted key (including cascade deletes) so a worker deletes the object.
CREATE TABLE video.storage_tombstones (
  storage_key text PRIMARY KEY,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION video.record_tombstone() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO video.storage_tombstones (storage_key) VALUES (OLD.storage_key)
  ON CONFLICT DO NOTHING;
  RETURN OLD;
END $$;
CREATE TRIGGER video_assets_tombstone AFTER DELETE ON video.video_assets
  FOR EACH ROW EXECUTE FUNCTION video.record_tombstone();

CREATE TABLE video.hashtags (
  id  uuid PRIMARY KEY,
  tag citext NOT NULL UNIQUE CHECK (tag ~ '^[^[:space:]#]{1,60}$')
);
CREATE TABLE video.video_hashtags (
  video_id   uuid NOT NULL REFERENCES video.videos(id) ON DELETE CASCADE,
  hashtag_id uuid NOT NULL REFERENCES video.hashtags(id),
  PRIMARY KEY (video_id, hashtag_id)
);
-- Serves "videos for a hashtag"
CREATE INDEX video_hashtags_tag_idx ON video.video_hashtags (hashtag_id, video_id);

-- Captions are first-class (VISION.md goal 3). Segments, not one text blob, so
-- search results can seek to the matching second and WER can be scored per cue.
CREATE TABLE video.captions (
  id               uuid PRIMARY KEY,
  video_id         uuid        NOT NULL REFERENCES video.videos(id) ON DELETE CASCADE,
  language_code    text        NOT NULL REFERENCES video.languages(code),
  source           text        NOT NULL CHECK (source IN ('ASR','CREATOR')),
  status           text        NOT NULL CHECK (status IN ('PENDING','READY','FAILED')),
  model            text,                     -- e.g. model name; needed to compare WER across models
  model_version    text,
  avg_confidence   real        CHECK (avg_confidence BETWEEN 0 AND 1),
  vtt_storage_key  text,                     -- rendered artifact, derived (D5)
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (video_id, language_code, source),
  CHECK (status <> 'READY' OR vtt_storage_key IS NOT NULL),
  CHECK (source <> 'ASR' OR model IS NOT NULL)
);
CREATE INDEX captions_language_idx ON video.captions (language_code);

CREATE TABLE video.caption_segments (
  caption_id  uuid NOT NULL REFERENCES video.captions(id) ON DELETE CASCADE,
  seq         int  NOT NULL CHECK (seq >= 0),
  start_ms    int  NOT NULL CHECK (start_ms >= 0),
  end_ms      int  NOT NULL,
  text        text NOT NULL,
  -- D1: derived search column. Accent-insensitive on purpose: people type
  -- Yoruba/Igbo without tone marks and dots. 'simple' config because Postgres
  -- ships no stemmers for these languages.
  text_tsv    tsvector GENERATED ALWAYS AS
                (to_tsvector('simple', shared.immutable_unaccent(text))) STORED,
  PRIMARY KEY (caption_id, seq),
  CHECK (end_ms > start_ms)
);
-- Serves transcript search (full-text)
CREATE INDEX caption_segments_tsv_idx ON video.caption_segments USING gin (text_tsv);
-- Serves fuzzy / misspelled search (Pidgin spelling varies a lot)
CREATE INDEX caption_segments_trgm_idx
  ON video.caption_segments USING gin (lower(shared.immutable_unaccent(text)) gin_trgm_ops);

-- ====================================================================
-- feed
-- ====================================================================
CREATE TABLE feed.ranking_components (
  code        text PRIMARY KEY,     -- RECENCY, ENGAGEMENT, FOLLOWING, TOPIC
  description text NOT NULL
);
CREATE TABLE feed.ranking_modes (
  code        text PRIMARY KEY,     -- DEFAULT, CHRONOLOGICAL, FOLLOWING_ONLY, TOPIC_FOCUSED
  description text NOT NULL
);
-- Each mode is defined by published weights, so "DEFAULT" is not a black box.
CREATE TABLE feed.ranking_mode_weights (
  mode_code      text NOT NULL REFERENCES feed.ranking_modes(code),
  component_code text NOT NULL REFERENCES feed.ranking_components(code),
  weight         numeric(4,3) NOT NULL CHECK (weight BETWEEN 0 AND 1),
  PRIMARY KEY (mode_code, component_code)
);
CREATE INDEX ranking_mode_weights_component_idx ON feed.ranking_mode_weights (component_code);

CREATE TABLE feed.user_feed_settings (
  user_id             uuid PRIMARY KEY,
  ranking_mode        text    NOT NULL DEFAULT 'DEFAULT' REFERENCES feed.ranking_modes(code),
  data_saver          boolean NOT NULL DEFAULT false,
  monthly_data_cap_mb int     CHECK (monthly_data_cap_mb > 0),   -- NULL = no cap
  prefetch_cap_mb     int     NOT NULL DEFAULT 5 CHECK (prefetch_cap_mb >= 0)
);
CREATE INDEX user_feed_settings_mode_idx ON feed.user_feed_settings (ranking_mode);

-- Per-user overrides on top of the mode's weights.
CREATE TABLE feed.user_ranking_weights (
  user_id        uuid NOT NULL REFERENCES feed.user_feed_settings(user_id) ON DELETE CASCADE,
  component_code text NOT NULL REFERENCES feed.ranking_components(code),
  weight         numeric(4,3) NOT NULL CHECK (weight BETWEEN 0 AND 1),
  PRIMARY KEY (user_id, component_code)
);
CREATE INDEX user_ranking_weights_component_idx ON feed.user_ranking_weights (component_code);

-- Client-reported bytes (the server cannot see CDN-served bytes). Partitioned
-- monthly; old months are dropped, not deleted row by row. The default
-- partition catches rows until an operator/job creates the month's partition.
CREATE TABLE feed.usage_events (
  id             uuid        NOT NULL,
  user_id        uuid        NOT NULL,
  video_id       uuid        NOT NULL,
  rendition_code text        NOT NULL,    -- video.renditions.code; no FK (cross-module)
  bytes          bigint      NOT NULL CHECK (bytes >= 0),
  occurred_at    timestamptz NOT NULL,
  PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);
CREATE TABLE feed.usage_events_default PARTITION OF feed.usage_events DEFAULT;
-- Serves "bytes used this month by user" for the budget check
CREATE INDEX usage_events_user_idx ON feed.usage_events (user_id, occurred_at);

CREATE TABLE feed.seen_videos (
  user_id  uuid        NOT NULL,
  video_id uuid        NOT NULL,
  seen_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, video_id)
);
-- Serves trimming old rows
CREATE INDEX seen_videos_age_idx ON feed.seen_videos (seen_at);

-- D2: read model fed by video events; rebuildable.
CREATE TABLE feed.candidates (
  video_id     uuid PRIMARY KEY,
  creator_id   uuid        NOT NULL,
  language     text,
  published_at timestamptz NOT NULL,
  duration_ms  int         NOT NULL CHECK (duration_ms > 0)
);
-- Serves the chronological and default feed, cursor on (published_at, video_id)
CREATE INDEX candidates_pub_idx ON feed.candidates (published_at DESC, video_id DESC);
-- Serves FOLLOWING_ONLY mode
CREATE INDEX candidates_creator_idx ON feed.candidates (creator_id, published_at DESC);

-- D3: read model fed by engagement events; rebuildable.
CREATE TABLE feed.candidate_stats (
  video_id uuid PRIMARY KEY REFERENCES feed.candidates(video_id) ON DELETE CASCADE,
  likes    bigint      NOT NULL DEFAULT 0 CHECK (likes >= 0),
  comments bigint      NOT NULL DEFAULT 0 CHECK (comments >= 0),
  views    bigint      NOT NULL DEFAULT 0 CHECK (views >= 0),
  as_of    timestamptz NOT NULL DEFAULT now()
);

-- ====================================================================
-- social
-- ====================================================================
CREATE TABLE social.follows (
  follower_id uuid        NOT NULL,
  followee_id uuid        NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (follower_id, followee_id),
  CHECK (follower_id <> followee_id)
);
-- Serves "who follows X" (the PK serves "whom does X follow")
CREATE INDEX follows_followee_idx ON social.follows (followee_id, created_at DESC);

CREATE TABLE social.blocks (
  blocker_id uuid        NOT NULL,
  blocked_id uuid        NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (blocker_id, blocked_id),
  CHECK (blocker_id <> blocked_id)
);

CREATE TABLE social.comments (
  id         uuid PRIMARY KEY,
  video_id   uuid        NOT NULL,
  author_id  uuid        NOT NULL,
  parent_id  uuid        REFERENCES social.comments(id) ON DELETE CASCADE,
  body       text        NOT NULL CHECK (length(body) BETWEEN 1 AND 2200),
  status     text        NOT NULL DEFAULT 'VISIBLE' CHECK (status IN ('VISIBLE','HIDDEN','REMOVED')),
  created_at timestamptz NOT NULL DEFAULT now()
);
-- Serves top-level comments of a video, cursor-paginated
CREATE INDEX comments_video_idx ON social.comments (video_id, created_at, id) WHERE parent_id IS NULL;
-- Serves replies of a comment (also the FK index for parent_id)
CREATE INDEX comments_parent_idx ON social.comments (parent_id, created_at, id) WHERE parent_id IS NOT NULL;
-- Serves deleting everything an author wrote (account deletion)
CREATE INDEX comments_author_idx ON social.comments (author_id);

-- ====================================================================
-- engagement
-- ====================================================================
-- PK makes a double-like impossible by construction.
CREATE TABLE engagement.video_likes (
  user_id    uuid        NOT NULL,
  video_id   uuid        NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, video_id)
);
-- Serves recounting likes per video (reconciliation of D4)
CREATE INDEX video_likes_video_idx ON engagement.video_likes (video_id);

CREATE TABLE engagement.view_events (
  id          uuid        NOT NULL,
  video_id    uuid        NOT NULL,
  user_id     uuid,                       -- NULL for anonymous views
  watched_ms  int         NOT NULL CHECK (watched_ms >= 0),
  completed   boolean     NOT NULL DEFAULT false,
  occurred_at timestamptz NOT NULL,
  PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);
CREATE TABLE engagement.view_events_default PARTITION OF engagement.view_events DEFAULT;
-- Serves recounting views per video
CREATE INDEX view_events_video_idx ON engagement.view_events (video_id, occurred_at);

-- D4: cached counters, own row to isolate write contention from video rows.
CREATE TABLE engagement.video_counters (
  video_id   uuid PRIMARY KEY,
  likes      bigint      NOT NULL DEFAULT 0 CHECK (likes >= 0),
  comments   bigint      NOT NULL DEFAULT 0 CHECK (comments >= 0),
  views      bigint      NOT NULL DEFAULT 0 CHECK (views >= 0),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- ====================================================================
-- moderation
-- ====================================================================
CREATE TABLE moderation.reports (
  id          uuid PRIMARY KEY,
  reporter_id uuid        NOT NULL,
  target_type text        NOT NULL CHECK (target_type IN ('VIDEO','COMMENT','ACCOUNT')),
  target_id   uuid        NOT NULL,
  reason_code text        NOT NULL
                CHECK (reason_code IN ('CHILD_SAFETY','COPYRIGHT','HARASSMENT','VIOLENCE','SPAM','OTHER')),
  details     text        NOT NULL DEFAULT '' CHECK (length(details) <= 2000),
  status      text        NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','ACTIONED','DISMISSED')),
  created_at  timestamptz NOT NULL DEFAULT now()
);
-- One open report per reporter per target: stops report-flooding
CREATE UNIQUE INDEX reports_open_unique_idx
  ON moderation.reports (reporter_id, target_type, target_id) WHERE status = 'OPEN';
-- Serves the moderator queue (oldest open first)
CREATE INDEX reports_queue_idx ON moderation.reports (created_at, id) WHERE status = 'OPEN';

-- Append-only audit log: every state-changing action, with actor, time, reason.
CREATE TABLE moderation.actions (
  id          uuid PRIMARY KEY,
  report_id   uuid        REFERENCES moderation.reports(id),
  actor_id    uuid        NOT NULL,       -- pseudonymous id only; no personal data
  action_type text        NOT NULL
                CHECK (action_type IN ('TAKEDOWN','RESTORE','SUSPEND_ACCOUNT','DISMISS_REPORT','HIDE_COMMENT')),
  target_type text        NOT NULL CHECK (target_type IN ('VIDEO','COMMENT','ACCOUNT')),
  target_id   uuid        NOT NULL,
  reason      text        NOT NULL CHECK (length(btrim(reason)) > 0),
  occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX actions_report_idx ON moderation.actions (report_id);
-- Serves "history of a target"
CREATE INDEX actions_target_idx ON moderation.actions (target_type, target_id, occurred_at);

CREATE FUNCTION moderation.forbid_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'moderation.actions is append-only' USING ERRCODE = 'P0001';
END $$;
CREATE TRIGGER actions_append_only BEFORE UPDATE OR DELETE ON moderation.actions
  FOR EACH ROW EXECUTE FUNCTION moderation.forbid_change();
CREATE TRIGGER actions_no_truncate BEFORE TRUNCATE ON moderation.actions
  FOR EACH STATEMENT EXECUTE FUNCTION moderation.forbid_change();

